import{_ as s,o as n,c as e,a2 as i}from"./chunks/framework.ClgMjOt7.js";const h=JSON.parse('{"title":"アーキテクチャ","description":"PalleriaのAndroid・Rustコードの構成。","frontmatter":{"title":"アーキテクチャ","description":"PalleriaのAndroid・Rustコードの構成。"},"headers":[],"relativePath":"development/architecture.md","filePath":"development/architecture.md","lastUpdated":1789107345000}'),p={name:"development/architecture.md"};function t(l,a,o,r,d,c){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="アーキテクチャ" tabindex="-1">アーキテクチャ <a class="header-anchor" href="#アーキテクチャ" aria-label="Permalink to &quot;アーキテクチャ&quot;">​</a></h1><h2 id="ディレクトリ構成" tabindex="-1">ディレクトリ構成 <a class="header-anchor" href="#ディレクトリ構成" aria-label="Permalink to &quot;ディレクトリ構成&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Palleria/</span></span>
<span class="line"><span>├─ app/                         Androidアプリ</span></span>
<span class="line"><span>│  └─ src/main/java/com/yunfie/illustia/</span></span>
<span class="line"><span>│     ├─ ui/                    Compose UIと画面</span></span>
<span class="line"><span>│     ├─ data/                  API・リポジトリ・永続化</span></span>
<span class="line"><span>│     ├─ models/                アプリとAPIのモデル</span></span>
<span class="line"><span>│     ├─ pallasync/             同期機能のAndroid側</span></span>
<span class="line"><span>│     ├─ settings/              設定</span></span>
<span class="line"><span>│     ├─ wallpaper/             壁紙機能</span></span>
<span class="line"><span>│     └─ widget/                ホーム画面ウィジェット</span></span>
<span class="line"><span>├─ rust/</span></span>
<span class="line"><span>│  ├─ pixiv-api/                Pixiv APIとUniFFI公開層</span></span>
<span class="line"><span>│  └─ pallasync-core/           同期コア</span></span>
<span class="line"><span>├─ fdroid/                      F-Droidメタデータ</span></span>
<span class="line"><span>└─ docs/                        VitePressドキュメント</span></span></code></pre></div><h2 id="ui" tabindex="-1">UI <a class="header-anchor" href="#ui" aria-label="Permalink to &quot;UI&quot;">​</a></h2><p>画面はJetpack Composeで実装し、デザインシステムにはMiuix KMPを使用します。新しい画面やコンポーネントは、既存のMiuixテーマ、ナビゲーション、ポップアップ管理のパターンに合わせてください。</p><h2 id="データフロー" tabindex="-1">データフロー <a class="header-anchor" href="#データフロー" aria-label="Permalink to &quot;データフロー&quot;">​</a></h2><p>UIはViewModelから状態を受け取り、Repositoryとデータ層を通じてネットワーク、データベース、設定へアクセスします。長時間処理はコルーチンで実行し、画面のライフサイクルに合わせてキャンセルできる構成を保ちます。</p><h2 id="rust連携" tabindex="-1">Rust連携 <a class="header-anchor" href="#rust連携" aria-label="Permalink to &quot;Rust連携&quot;">​</a></h2><p><code>rust/pixiv-api</code>はRustライブラリをビルドし、UniFFI経由でKotlinバインディングを生成します。Gradleの<code>preBuild</code>は、ホスト向けバインディング生成とAndroid ABI向けライブラリビルドに依存します。</p><p>対象ABI:</p><ul><li><code>arm64-v8a</code></li><li><code>armeabi-v7a</code></li><li><code>x86_64</code></li></ul><h2 id="android統合" tabindex="-1">Android統合 <a class="header-anchor" href="#android統合" aria-label="Permalink to &quot;Android統合&quot;">​</a></h2><p>アプリはURL共有、テキスト共有、ウィジェット、ライブ壁紙、Androidアカウント同期などのプラットフォーム機能を含みます。Manifestや公開コンポーネントを変更するときは、権限と<code>exported</code>設定を慎重に確認してください。</p>`,13)])])}const m=s(p,[["render",t]]);export{h as __pageData,m as default};
